def solve(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # wall color: colors forming runs >=2; dot color: the other non-bg color
    wallset=set()
    for r in range(h):
        c=0
        while c<w:
            if g[r][c]!=bg:
                s=c
                while c<w and g[r][c]==g[r][s]: c+=1
                if c-s>=2: wallset.add(g[r][s])
            else: c+=1
    for c in range(w):
        r=0
        while r<h:
            if g[r][c]!=bg:
                s=r
                while r<h and g[r][c]==g[s][c]: r+=1
                if r-s>=2: wallset.add(g[s][c])
            else: r+=1
    wallcol=list(wallset)[0]
    dotcol=[x for x in cnt if x!=bg and x!=wallcol][0]
    dots=[(r,c) for r in range(h) for c in range(w) if g[r][c]==dotcol]
    # wall segments
    vwalls=[]; hwalls=[]
    for r in range(h):
        c=0
        while c<w:
            if g[r][c]!=bg and g[r][c]==wallcol:
                s=c
                while c<w and g[r][c]==wallcol: c+=1
                hwalls.append((r,s,c-1))
            else: c+=1
    for c in range(w):
        r=0
        while r<h:
            if g[r][c]!=bg and g[r][c]==wallcol:
                s=r
                while r<h and g[r][c]==wallcol: r+=1
                vwalls.append((s,r-1,c))
            else: r+=1
    out=[r[:] for r in g]
    for (r,c) in dots:
        out[r][c]=4
        # vertical walls: use row-span containment; horizontal: column-span
        if vwalls:
            spans=[(s,e,cv) for s,e,cv in vwalls]
            containing=[sp for sp in spans if sp[0]<=r<=sp[1]]
            if len(containing)==1:
                seg=containing[0]; other=[sp for sp in spans if sp not in containing][0]
                # beam toward containing wall
                d=-1 if c<seg[2] else 1
                cc=c+d
                while 0<=cc<w and g[r][cc]==bg:
                    out[r][cc]=dotcol; cc+=d
                # copy toward other wall's span
                dr=other[0]-seg[0]
                r2=r+dr
                # corridor fill in copy row between the two walls
                minc=min(seg[2],other[2]); maxc=max(seg[2],other[2])
                for cc in range(minc+1,maxc):
                    if g[r2][cc]==bg: out[r2][cc]=dotcol
            else:
                # fallback: nearest wall
                best=min(spans,key=lambda sp:abs(sp[2]-c))
                d=-1 if c<best[2] else 1
                cc=c+d
                while 0<=cc<w and g[r][cc]==bg:
                    out[r][cc]=dotcol; cc+=d
        else:
            spans=[(r2,s,e) for r2,s,e in hwalls]
            containing=[sp for sp in spans if sp[0]<=c<=sp[1]]
            if len(containing)==1:
                seg=containing[0]; other=[sp for sp in spans if sp not in containing][0]
                d=1 if r>seg[0] else -1
                rr=r+d
                while 0<=rr<h and g[rr][c]==bg:
                    out[rr][c]=dotcol; rr+=d
                dr=other[0]-seg[0]
                r2=r+dr
                minr=min(seg[0],other[0]); maxr=max(seg[0],other[0])
                for rr in range(minr+1,maxr):
                    if g[rr][c]==bg: out[rr][c]=dotcol
            else:
                best=min(spans,key=lambda sp:abs(sp[0]-r))
                d=1 if r>best[0] else -1
                rr=r+d
                while 0<=rr<h and g[rr][c]==bg:
                    out[rr][c]=dotcol; rr+=d
    return out

